SELECT name, LEAD(finish_seconds)
  OVER (ORDER BY finish_seconds) AS next_sec
FROM results;

SELECT name, SUM(finish_seconds)
  OVER (ORDER BY finish_seconds) AS running_total
FROM results;

SELECT RANK() OVER (ORDER BY sec) AS r,
       ROW_NUMBER() OVER (ORDER BY sec) AS rn
FROM results;

SELECT NTILE(4) OVER (
  ORDER BY finish_seconds) AS q
FROM results;
